push.css:
.fxs .dp{--pr:0px;--pushA:#FF004D;--pushB:#7E2553;--pushC:#FF77A8;--rim:#C2C3C7;--rimD:#000000;--pushFace:#FF004D}
.fxs .push.dp{background:none;box-shadow:none;border-radius:0;animation:fxdpBob .9s step-end infinite,fxdpPop .36s step-end both}
.fxs .push.dp span{color:transparent;text-shadow:none}
.fxs .push.dp::after{inset:-34px -34px -44px;border:0;border-radius:0;
  background:linear-gradient(#FFEC27,#FFEC27) 5px 0/calc(100% - 10px) 5px no-repeat,linear-gradient(#FFEC27,#FFEC27) 5px 100%/calc(100% - 10px) 5px no-repeat,
    linear-gradient(#FFEC27,#FFEC27) 0 5px/5px calc(100% - 10px) no-repeat,linear-gradient(#FFEC27,#FFEC27) 100% 5px/5px calc(100% - 10px) no-repeat;
  animation:fxdpRing 1.2s steps(4) infinite}
@keyframes fxdpRing{0%{transform:scale(.94);opacity:1}100%{transform:scale(1.22);opacity:0}}
@keyframes fxdpBob{0%,100%{transform:translateY(0)}16.6%{transform:translateY(-5px)}33.3%{transform:translateY(-10px)}50%{transform:translateY(-15px)}
  66.6%{transform:translateY(-10px)}83.3%{transform:translateY(-5px)}}
@keyframes fxdpPop{0%{scale:.25}25%{scale:.5}50%{scale:.8}75%{scale:1.08}100%{scale:1}}
.fxs .dp .dpf{position:absolute;left:-20px;top:-20px;width:240px;height:150px;pointer-events:none;font-style:normal}
